CASE INNER JOIN expansion and exact numeric keys
QUERY SELECT orders.oid, customers.name, orders.amt FROM orders INNER JOIN customers ON orders.cust = customers.cust_key
RESULT {"columns":["orders.oid","customers.name","orders.amt"],"rows":[[10,"alpha",100],[11,"alpha",50.5],[12,"alpha",25],[13,"beta",7],[14,"gamma",9]],"row_count":5}
CASE text and numeric keys do not cross-match
QUERY SELECT m_l.v, m_r.w FROM m_l INNER JOIN m_r ON m_l.k = m_r.k ORDER BY m_r.w
RESULT {"columns":["m_l.v","m_r.w"],"rows":[["c","W2"],["b","W3"]],"row_count":2}

CASE WHERE after join expansion
QUERY SELECT orders.oid, customers.name FROM orders INNER JOIN customers ON orders.cust = customers.cust_key WHERE orders.oid >= 12 AND name = "alpha"
RESULT {"columns":["orders.oid","customers.name"],"rows":[[12,"alpha"]],"row_count":1}
CASE ORDER BY then LIMIT
QUERY SELECT orders.oid, customers.name FROM orders INNER JOIN customers ON orders.cust = customers.cust_key ORDER BY orders.oid DESC LIMIT 2
RESULT {"columns":["orders.oid","customers.name"],"rows":[[14,"gamma"],[13,"beta"]],"row_count":2}
CASE LIMIT zero preserves columns
QUERY SELECT orders.oid, customers.name FROM orders INNER JOIN customers ON orders.cust = customers.cust_key LIMIT 0
RESULT {"columns":["orders.oid","customers.name"],"rows":[],"row_count":0}
